"use client";

import { useState, useRef, useEffect } from "react";
import { useRouter } from "next/navigation";
import { 
  ArrowLeft, Download, Share2, CheckCircle2, 
  Sparkles, Layout, RotateCw, Image as ImageIcon,
  Check, Info, Loader2, ShieldCheck, Globe
} from "lucide-react";
import { toPng } from "html-to-image";
import { supabase } from "@/lib/supabase";

// --- 🏰 DESIGN 1: THE EXECUTIVE MINIMAL (Modern & Clean) ---
const MinimalistElite = ({ store, products, qrCode }: any) => (
  <div className="w-[1080px] h-[1080px] bg-white relative overflow-hidden flex flex-col p-16 font-sans">
    {/* Top Brand Bar */}
    <div className="flex justify-between items-start mb-10">
      <div className="flex items-center gap-6">
        <img src={store?.logo_url} crossOrigin="anonymous" className="w-28 h-28 rounded-2xl object-cover shadow-lg border border-gray-100" alt="" />
        <div>
          <h2 className="text-[#043927] text-5xl font-black uppercase tracking-tighter">{store?.name}</h2>
          <p className="text-emerald-600 text-xl font-bold uppercase tracking-widest mt-1">Official Storefront</p>
        </div>
      </div>
    </div>

    {/* Pitch Section */}
    <div className="mb-12 max-w-[700px]">
      <h1 className="text-[#043927] text-7xl font-black leading-[1.1] tracking-tighter mb-6">
        SHOP 24/7. <br/> <span className="text-gray-400 font-light italic">NO DM STRESS.</span>
      </h1>
      <p className="text-gray-500 text-2xl leading-relaxed font-medium">
        {store?.description || "Browse our full collection, see prices instantly, and order without sending a single DM. Your shopping experience, upgraded."}
      </p>
    </div>

    {/* Styled Product Grid */}
    <div className="flex-1 flex gap-6 items-center">
      {products.slice(0, 3).map((p: any, i: number) => (
        <div key={i} className="flex-1 aspect-[4/5] bg-gray-50 rounded-[2rem] overflow-hidden shadow-2xl border-4 border-white relative group">
          <img src={p.display_image} crossOrigin="anonymous" className="w-full h-full object-cover" alt="" />
          <div className="absolute bottom-0 inset-x-0 p-6 bg-gradient-to-t from-black/80 to-transparent">
            <p className="text-white font-black text-3xl">₦{p.price?.toLocaleString()}</p>
          </div>
        </div>
      ))}
    </div>

    {/* Footer with QR on the Right */}
    <div className="mt-12 pt-12 border-t border-gray-100 flex justify-between items-center">
      <div>
        <p className="text-[#043927] font-black text-3xl">storelink.ng/{store?.slug}</p>
        <p className="text-emerald-600 font-bold uppercase tracking-widest text-sm mt-2 flex items-center gap-2">
          <ShieldCheck size={18} /> Verified Professional Vendor
        </p>
      </div>
      <div className="flex items-center gap-6 bg-gray-50 p-4 rounded-3xl border border-gray-100">
        <div className="text-right">
           <p className="text-[#043927] font-black text-xl uppercase italic">Scan to Browse</p>
           <p className="text-gray-400 text-sm font-bold">Instantly Shop Now</p>
        </div>
        <img src={qrCode} crossOrigin="anonymous" className="w-24 h-24" alt="QR" />
      </div>
    </div>
  </div>
);

// --- 🏰 DESIGN 2: THE "EMPIRE BLACK" (Sales Focused) ---
const EmpireBlack = ({ store, products, qrCode }: any) => (
  <div className="w-[1080px] h-[1080px] bg-[#0A0A0A] relative overflow-hidden flex flex-col p-20 text-white">
    <div className="absolute top-0 right-0 w-1/2 h-full bg-[#043927]/10 skew-x-12 translate-x-20" />
    
    <div className="relative z-10 flex items-center gap-6 mb-16">
      <img src={store?.logo_url} crossOrigin="anonymous" className="w-24 h-24 rounded-full border-2 border-emerald-500 p-1" alt="" />
      <h2 className="text-4xl font-black tracking-tighter uppercase italic">{store?.name}</h2>
    </div>

    <div className="relative z-10 grid grid-cols-12 gap-10 flex-1">
      <div className="col-span-7 space-y-8">
        <h1 className="text-8xl font-black tracking-tighter leading-[0.9] uppercase italic text-emerald-500">
          STOP <br/> ASKING <br/> <span className="text-white">"HOW MUCH"</span>
        </h1>
        <p className="text-2xl text-gray-400 font-medium leading-relaxed italic">
          We've moved to a professional storefront. Browse all products, see prices, and check out instantly.
        </p>
        <div className="flex gap-4">
          {products.slice(0, 3).map((p: any, i: number) => (
             <div key={i} className="w-32 h-32 rounded-2xl border-2 border-emerald-500/30 overflow-hidden rotate-3 first:-rotate-6 shadow-2xl">
                <img src={p.display_image} crossOrigin="anonymous" className="w-full h-full object-cover" alt="" />
             </div>
          ))}
        </div>
      </div>

      <div className="col-span-5 flex flex-col justify-end items-end space-y-6">
        <div className="bg-white p-6 rounded-[3rem] shadow-[0_0_50px_rgba(16,185,129,0.3)]">
          <img src={qrCode} crossOrigin="anonymous" className="w-56 h-56" alt="QR" />
        </div>
        <div className="text-right">
          <p className="text-emerald-500 font-black text-2xl uppercase italic">Shop Our Catalog</p>
          <p className="text-white/40 font-mono text-xl lowercase">storelink.ng/{store?.slug}</p>
        </div>
      </div>
    </div>
  </div>
);

// --- 🚀 MAIN STUDIO PAGE ---

export default function FlyerStudio() {
  const router = useRouter();
  const exportRef = useRef<HTMLDivElement>(null);
  
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [lastGeneratedFlyer, setLastGeneratedFlyer] = useState<string | null>(null);
  const [store, setStore] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [designIndex, setDesignIndex] = useState(0);

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return router.push("/login");

      const { data: storeData } = await supabase.from("stores").select("*").eq("owner_id", user.id).single();
      const { data: productsData } = await supabase.from("products").select("*").eq("store_id", storeData?.id).order('created_at', { ascending: false });

      const resolveUrl = (path: any, bucket: string) => {
        if (!path) return "";
        const actualPath = Array.isArray(path) ? path[0] : path;
        if (actualPath.startsWith('http')) return actualPath;
        const { data } = supabase.storage.from(bucket).getPublicUrl(actualPath);
        return data.publicUrl;
      };

      const items = (productsData || []).map(p => ({
        ...p, display_image: resolveUrl(p.image_urls, 'products')
      }));

      setStore({ ...storeData, logo_url: resolveUrl(storeData?.logo_url, 'stores') });
      setAllProducts(items);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const toggleProduct = (id: string) => {
    if (selectedIds.includes(id)) {
      setSelectedIds(selectedIds.filter(i => i !== id));
    } else if (selectedIds.length < 3) {
      setSelectedIds([...selectedIds, id]);
    }
  };

  const downloadFlyer = async () => {
    if (!exportRef.current) return;
    setGenerating(true);
    await new Promise(r => setTimeout(r, 800));

    try {
      const dataUrl = await toPng(exportRef.current, { cacheBust: true, pixelRatio: 2, backgroundColor: '#ffffff' });
      const link = document.createElement('a');
      link.download = `${store?.name}-Empire-Flyer.png`;
      link.href = dataUrl;
      link.click();
      setLastGeneratedFlyer(dataUrl);
      setShowSuccess(true);
    } catch (err) { console.error(err); } finally { setGenerating(false); }
  };

  const selectedProducts = allProducts.filter(p => selectedIds.some(id => String(id) === String(p.id)));
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=600x600&color=043927&data=https://storelink.ng/${store?.slug}`;

  if (loading) return (
    <div className="h-screen flex flex-col items-center justify-center bg-[#0A0A0A] text-white">
      <Loader2 className="animate-spin text-emerald-500 mb-4" size={40} />
      <p className="font-black uppercase italic tracking-widest text-emerald-500/50">Initializing Studio...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#0A0A0A] text-white font-sans">
      {/* Navbar */}
      <nav className="border-b border-white/5 p-6 flex justify-between items-center bg-black/50 backdrop-blur-xl sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <button onClick={() => router.back()} className="p-2 hover:bg-white/5 rounded-full"><ArrowLeft /></button>
          <h1 className="font-black uppercase italic text-xl tracking-tighter">Empire Studio</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setDesignIndex((prev) => (prev + 1) % 2)} className="bg-white/5 border border-white/10 px-6 py-2.5 rounded-2xl flex items-center gap-2 font-bold text-xs uppercase tracking-widest hover:bg-white/10">
            <RotateCw size={14} /> Change Style
          </button>
        </div>
      </nav>

      <div className="max-w-[1600px] mx-auto p-6 grid grid-cols-1 lg:grid-cols-12 gap-10">
        
        {/* Left: Settings (Col 4) */}
        <div className="lg:col-span-4 space-y-8">
          <div className="bg-white/5 border border-white/10 p-8 rounded-[2.5rem] backdrop-blur-md">
            <h2 className="font-black uppercase italic text-lg mb-6 flex items-center gap-2 text-emerald-500">
              <Layout size={20}/> 1. Select 3 Products
            </h2>
            <div className="grid grid-cols-3 gap-3">
              {allProducts.map((p) => {
                const isSelected = selectedIds.includes(p.id);
                return (
                  <button key={p.id} onClick={() => toggleProduct(p.id)} className={`relative aspect-square rounded-2xl overflow-hidden transition-all border-2 ${isSelected ? 'border-emerald-500 scale-95 shadow-[0_0_20px_rgba(16,185,129,0.4)]' : 'border-white/10 opacity-30 hover:opacity-100'}`}>
                    <img src={p.display_image} className="w-full h-full object-cover" alt="" />
                    {isSelected && (
                      <div className="absolute inset-0 bg-emerald-500/40 flex items-center justify-center">
                        <div className="bg-white text-emerald-600 rounded-full p-1.5 shadow-2xl"><Check size={18} strokeWidth={4} /></div>
                      </div>
                    )}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="bg-emerald-600 p-8 rounded-[2.5rem] shadow-2xl shadow-emerald-500/20 group relative overflow-hidden">
            <h2 className="font-black uppercase italic text-lg mb-4 text-emerald-950 flex items-center gap-2"><Sparkles size={20} /> 2. Generate</h2>
            <button 
              disabled={selectedIds.length < 3 || generating} 
              onClick={downloadFlyer} 
              className="w-full py-6 bg-black text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl disabled:opacity-50 hover:scale-[1.02] transition-all flex items-center justify-center gap-4"
            >
              {generating ? <Loader2 className="animate-spin" /> : <Download />} {generating ? "Rendering..." : "Save to Phone"}
            </button>
          </div>
        </div>

        {/* Right: Preview (Col 8) */}
        <div className="lg:col-span-8">
           <div className="bg-[#111] rounded-[3.5rem] border border-white/5 p-8 lg:p-16 flex flex-col items-center justify-center min-h-[700px] relative">
              <div className="absolute top-10 flex gap-4 text-gray-600 font-bold uppercase tracking-[0.3em] text-[10px] items-center">
                 <div className="h-px w-10 bg-white/10" /> Professional Preview <div className="h-px w-10 bg-white/10" />
              </div>
              
              <div 
                ref={exportRef} 
                className="shadow-[0_40px_100px_rgba(0,0,0,0.8)]"
                style={{ width: '1080px', height: '1080px', transform: 'scale(0.48)', transformOrigin: 'center center', flexShrink: 0 }}
              >
                 {selectedIds.length === 3 ? (
                    <>
                      {designIndex === 0 && <MinimalistElite store={store} products={selectedProducts} qrCode={qrUrl} />}
                      {designIndex === 1 && <EmpireBlack store={store} products={selectedProducts} qrCode={qrUrl} />}
                    </>
                 ) : (
                   <div className="w-full h-full bg-[#1A1A1A] flex flex-col items-center justify-center text-white/10 p-20 text-center border-4 border-dashed border-white/5">
                      <ImageIcon size={300} strokeWidth={0.5} />
                      <h2 className="text-8xl font-black uppercase italic tracking-tighter mt-10">Select 3 Items</h2>
                   </div>
                 )}
              </div>
           </div>
        </div>
      </div>

      {/* SCALE FIX FOR MOBILE PREVIEW */}
      <style jsx>{`
        @media (max-width: 1024px) {
          div[style*="scale(0.48)"] {
            transform: scale(0.28) !important;
          }
          .min-h-[700px] { min-h-[400px] !important; }
        }
        @media (max-width: 640px) {
          div[style*="scale(0.48)"] {
            transform: scale(0.22) !important;
          }
        }
      `}</style>
    </div>
  );
}